 {
  "turns": [
    {
      "speaker": "agent",
      "text": "Thank you for calling Nimbus Telecom. My name is Ravi. How can I help you today?",
      "tags": [
        "greeting"
      ]
    },
    {
      "speaker": "customer",
      "text": "Hi Ravi, I'm Emily Iyer. I'm really frustrated because my current data plan is way too expensive for what I actually use, and I need to change it immediately.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "I am sorry to hear that you are feeling frustrated with your current plan costs, Ms. Iyer. I can certainly help you look at some more affordable options.",
      "tags": [
        "empathy"
      ]
    },
    {
      "speaker": "agent",
      "text": "Before we look at the account details, could you please provide your account number and date of birth for verification?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Sure, my account number is 92346833 and my date of birth is 17/04/1985.",
      "tags": [
        "identity_verification"
      ]
    },
    {
      "speaker": "agent",
      "text": "Thank you. I see your account is registered at 259 Brigade Road. Is that still correct?",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Yes, that's correct. I also want to make sure my email is still emily.68@examplemail.com and my phone is 94477 19486.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Yes, those details are correct in our system. Now, based on your usage, I recommend the Basic Connect plan. It will be 25 dollars per month, and the change will take effect on the first of next month.",
      "tags": [
        "disclosure"
      ]
    },
    {
      "speaker": "customer",
      "text": "That sounds better, but I've had so many issues with this company lately. If this doesn't work out, I'm just going to cancel my service and switch to another provider.",
      "tags": [
        "churn_signal"
      ]
    },
    {
      "speaker": "agent",
      "text": "I understand your concerns. I will process the plan change now and send a confirmation SMS to your phone.",
      "tags": [
        "action:plan_change"
      ]
    },
    {
      "speaker": "agent",
      "text": "However, I've noticed a billing discrepancy on your account that I cannot resolve here. I need to escalate this to my supervisor to ensure the credit is applied correctly.",
      "tags": []
    },
    {
      "speaker": "customer",
      "text": "Fine, as long as it gets sorted. I just want a plan that makes sense.",
      "tags": []
    },
    {
      "speaker": "agent",
      "text": "Is there anything else I can assist you with today? To recap, I have updated your plan and escalated the billing issue to my manager. Goodbye!",
      "tags": [
        "closure"
      ]
    }
  ]
}
